function double(n) {
  return new Promise((resolve) => {
    setTimeout(() => resolve(n * 2), 10);
  });
}

double(5)
  .then((result) => double(result))
  .then((result) => console.log(result)); // 20

const fast = new Promise((resolve) => setTimeout(() => resolve("fast"), 10));
const slow = new Promise((resolve) => setTimeout(() => resolve("slow"), 50));

Promise.race([fast, slow]).then((winner) => console.log("race winner:", winner));
Promise.all([fast, slow]).then((results) => console.log("all results:", results));

function delay(ms, value) {
  return new Promise((resolve) => setTimeout(() => resolve(value), ms));
}

async function run() {
  const a = await delay(10, 2);
  const b = await delay(10, 3);
  console.log(a + b); // 5
}

run();

