function mayFail(shouldFail) {
  return new Promise((resolve, reject) => {
    if (shouldFail) {
      reject(new Error("Something went wrong"));
    } else {
      resolve("All good");
    }
  });
}

mayFail(true)
  .then((result) => console.log(result))
  .catch((err) => console.log("Caught:", err.message));

